%% EXPECT: rand_regression_ok
%% Regression: rand could not be seeded and had no function but uniform/1, so
%% seeded programs (PropEr runs, Cowlib's date property) drew different numbers
%% on every run. For each built-in algorithm and each seed form, the seeded
%% draws, exported states, jumps, shuffles and error reasons must be OTP 29's.
%% expected/0 is generated on OTP 29 by scripts/generate-rand-regression.escript
%% from observe/0; do not edit it by hand. Run this fixture on native Nera and
%% BEAM.
-module(rand_regression).
-export([test/0, observe/0]).

test() ->
    compare(expected(), observe()),
    process_state(),
    io:format("rand_regression_ok~n"),
    ok.

%% ---------------------------------------------------------------------------
%% Observations: every value a seed determines, as plain terms.

algs() -> [exsss, exro928ss, exrop, exs1024s, exsp, exs64, exsplus, exs1024, dummy].

seeds(dummy) ->
    %% The dummy generator alternates two values. From the seed [9], its normal
    %% draws are rejected forever, on OTP too.
    all_seeds() -- [[9]];
seeds(_) ->
    all_seeds().

all_seeds() ->
    [42, -12345, (1 bsl 100) + 3, {1, 2, 3}, {123456789, 987654321, 1 bsl 40}, [5, 7], [9]].

ranges() ->
    [1, 2, 6, 1000, (1 bsl 58) - 1, 1 bsl 58, (1 bsl 58) + 1,
     1 bsl 64, (1 bsl 64) + 1, 1000000000000000000000000000000, (1 bsl 200) + 7].

observe() ->
    lists:append(
      [[{default, rand:export_seed_s(rand:seed_s(default, 42))}],
       lists:append([observe_alg(Alg, Seed) || Alg <- algs(), Seed <- seeds(Alg)]),
       lists:append([observe_process(Alg) || Alg <- algs()]),
       observe_utilities(),
       observe_errors()]).

observe_alg(Alg, Seed) ->
    case outcome(fun() -> rand:seed_s(Alg, Seed) end) of
        {ok, S0} ->
            {Floats, S1} = draws(fun rand:uniform_s/1, 3, S0),
            {Ints, S2} = map_s(fun rand:uniform_s/2, ranges(), S1),
            {Reals, S3} = draws(fun rand:uniform_real_s/1, 3, S2),
            {Bytes, S4} = map_s(fun rand:bytes_s/2, [0, 1, 7, 8, 33], S3),
            {Normals, S5} = draws(fun rand:normal_s/1, 5, S4),
            {Scaled, S6} = rand:normal_s(10, 4, S5),
            {Shuffled, S7} = map_s(fun rand:shuffle_s/2,
                                   [[], [a], [a, b], [a, b, c], lists:seq(1, 20)], S6),
            Jumped = case outcome(fun() -> rand:jump(S7) end) of
                         {ok, J} ->
                             {After, _} = rand:uniform_s(1 bsl 64, J),
                             {rand:export_seed_s(J), After};
                         Error ->
                             Error
                     end,
            [{{Alg, Seed, seed}, rand:export_seed_s(S0)},
             {{Alg, Seed, uniform}, Floats},
             {{Alg, Seed, uniform_n}, Ints},
             {{Alg, Seed, uniform_real}, Reals},
             {{Alg, Seed, bytes}, Bytes},
             {{Alg, Seed, normal}, [Scaled | Normals]},
             {{Alg, Seed, shuffle}, Shuffled},
             {{Alg, Seed, jump}, Jumped},
             {{Alg, Seed, final}, rand:export_seed_s(S7)}];
        Error ->
            [{{Alg, Seed, seed}, Error}]
    end.

%% The process dictionary forms, run in a fresh process.
observe_process(Alg) ->
    in_process(
      fun() ->
              undefined = rand:export_seed(),
              Seeded = rand:seed(Alg, 42),
              Exported = rand:export_seed(),
              Exported = rand:export_seed_s(Seeded),
              Draws = [rand:uniform(), rand:uniform(100), rand:uniform(1 bsl 70),
                       rand:uniform_real(), rand:bytes(5)],
              Normals = [rand:normal(), rand:normal(1.0, 2.0)],
              Shuffled = rand:shuffle([a, b, c, d, e]),
              Jump = outcome(fun() -> rand:jump(), rand:uniform(1000) end),
              Mid = rand:export_seed(),
              Next = [rand:uniform(1 bsl 64) || _ <- lists:seq(1, 3)],
              %% Seeding from the exported state, and from the full state,
              %% resumes the same sequence.
              _ = rand:seed(Mid),
              Next = [rand:uniform(1 bsl 64) || _ <- lists:seq(1, 3)],
              _ = rand:seed(rand:seed_s(Mid)),
              Next = [rand:uniform(1 bsl 64) || _ <- lists:seq(1, 3)],
              [{{Alg, process, seed}, Exported},
               {{Alg, process, draws}, Draws},
               {{Alg, process, normal}, Normals},
               {{Alg, process, shuffle}, Shuffled},
               {{Alg, process, jump}, Jump},
               {{Alg, process, next}, Next},
               {{Alg, process, final}, rand:export_seed()}]
      end).

observe_utilities() ->
    CX0 = rand:mwc59_seed(42),
    CXs = lists:foldl(fun(_, [CX | _] = Acc) -> [rand:mwc59(CX) | Acc] end,
                      [CX0], lists:seq(1, 5)),
    [{splitmix64_next, [rand:splitmix64_next(X) || X <- [0, 42, -1, 1 bsl 70]]},
     {exsp_next, rand:exsp_next([1 | 2])},
     {exsp_jump, rand:exsp_jump([123 | 456])},
     {mwc59, CXs},
     {mwc59_values, [{rand:mwc59_value32(CX), rand:mwc59_value(CX), rand:mwc59_float(CX)}
                     || CX <- CXs]},
     {mwc59_seed, [rand:mwc59_seed(S) || S <- [0, 1, (1 bsl 58) - 1]]}].

observe_errors() ->
    S = rand:seed_s(exsss, 1),
    Cases =
        [{seed_unknown_alg, fun() -> rand:seed_s(foo, 1) end},
         {seed_float, fun() -> rand:seed_s(exsss, 1.5) end},
         {seed_empty_list, fun() -> rand:seed_s(exsss, []) end},
         {seed_zero_list, fun() -> rand:seed_s(exsss, [0, 0]) end},
         {seed_long_list, fun() -> rand:seed_s(exsss, [1, 2, 3]) end},
         {seed_atom_list, fun() -> rand:seed_s(exsss, [a]) end},
         {uniform_zero, fun() -> rand:uniform_s(0, S) end},
         {uniform_negative, fun() -> rand:uniform_s(-5, S) end},
         {uniform_float, fun() -> rand:uniform_s(1.0, S) end},
         {bytes_negative, fun() -> rand:bytes_s(-1, S) end},
         {bytes_float, fun() -> rand:bytes_s(1.0, S) end},
         {normal_negative_variance, fun() -> rand:normal_s(0, -1, S) end},
         {shuffle_not_list, fun() -> rand:shuffle_s(foo, S) end},
         {jump_exs64, fun() -> rand:jump(rand:seed_s(exs64, 1)) end},
         {mwc59_zero, fun() -> rand:mwc59(0) end},
         {mwc59_seed_large, fun() -> rand:mwc59_seed(1 bsl 58) end},
         {export_not_state, fun() -> rand:export_seed_s(foo) end}],
    [{{error_case, Name}, outcome(F)} || {Name, F} <- Cases].

draws(F, N, S0) ->
    lists:foldl(fun(_, {Acc, S}) -> {X, S1} = F(S), {Acc ++ [X], S1} end,
                {[], S0}, lists:seq(1, N)).

map_s(F, Args, S0) ->
    lists:foldl(fun(A, {Acc, S}) -> {X, S1} = F(A, S), {Acc ++ [X], S1} end,
                {[], S0}, Args).

outcome(F) ->
    try F() of
        Value -> {ok, Value}
    catch
        error:Reason -> {error, Reason}
    end.

in_process(F) ->
    Parent = self(),
    {Pid, Ref} = spawn_monitor(fun() -> Parent ! {self(), F()} end),
    receive
        {Pid, Result} ->
            receive {'DOWN', Ref, process, Pid, _} -> ok end,
            Result;
        {'DOWN', Ref, process, Pid, Reason} ->
            error({observer_died, Reason})
    end.

%% ---------------------------------------------------------------------------
%% Comparison. Normal draws may take the slow path through math:log/1 and
%% math:exp/1, whose last bit depends on the platform's C library, so they
%% are compared to a relative 1.0e-12; every other value must be identical.

compare([], []) ->
    ok;
compare([{Label, Expected} | Es], [{Label, Actual} | As]) ->
    case same(Label, Expected, Actual) of
        true -> compare(Es, As);
        false -> error({rand_mismatch, Label, Expected, Actual})
    end;
compare([{Label, _} | _], [{Other, _} | _]) ->
    error({rand_label_mismatch, Label, Other});
compare(Es, As) ->
    error({rand_count_mismatch, length(Es), length(As)}).

same({_, _, normal}, Expected, Actual) -> close(Expected, Actual);
same(_, Expected, Actual) -> Expected =:= Actual.

close(Xs, Ys) ->
    length(Xs) =:= length(Ys) andalso
        lists:all(fun({X, Y}) -> close_float(X, Y) end, lists:zip(Xs, Ys)).

close_float(X, Y) when is_float(X), is_float(Y) ->
    X =:= Y orelse abs(X - Y) =< 1.0e-12 * max(abs(X), abs(Y));
close_float(_, _) ->
    false.

%% ---------------------------------------------------------------------------
%% Behavior that depends on time and process identity, so it is not pinned.

process_state() ->
    %% A fresh process has no state until its first draw, which seeds the
    %% default algorithm in that process only.
    in_process(fun() ->
                       undefined = rand:export_seed(),
                       X = rand:uniform(),
                       true = is_float(X) andalso X >= 0.0 andalso X < 1.0,
                       {exsss, _} = rand:export_seed(),
                       _ = rand:seed(exsss, 7),
                       undefined = in_process(fun() -> rand:export_seed() end),
                       ok
               end),
    %% Two processes seeded from the clock and their identities draw
    %% different sequences.
    Draw = fun() -> [rand:uniform(1 bsl 64) || _ <- lists:seq(1, 4)] end,
    true = in_process(Draw) =/= in_process(Draw),
    %% seed/1 with an algorithm or default seeds from the same sources.
    in_process(fun() ->
                       {#{type := exro928ss}, _} = rand:seed(exro928ss),
                       {exro928ss, _} = rand:export_seed(),
                       _ = rand:seed(default),
                       {exsss, _} = rand:export_seed(),
                       ok
               end),
    ok.

